<script setup lang="ts">import{Head,Link,router}from'@inertiajs/vue3';import AdminLayout from'../../Layouts/AdminLayout.vue';defineProps<{items:any;filters:any}>();const remove=(id:number)=>confirm('Permanently delete this content?')&&router.delete(`/admin/content/${id}`);</script><template><Head title="Manage Content"/><AdminLayout><div class="flex justify-between"><h1 class="text-3xl font-extrabold">Content</h1><Link href="/admin/content/create" class="btn-primary">New content</Link></div><div class="card mt-8 overflow-auto"><table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="py-3">Title</th><th>Type</th><th>Status</th><th>Updated</th><th class="text-right">Actions</th></tr></thead><tbody><tr v-for="i in items.data" :key="i.id" class="border-b"><td class="py-4 font-bold">{{i.title}}</td><td class="capitalize">{{i.type.replace('_',' ')}}</td><td><span class="rounded-full bg-slate-100 px-3 py-1 capitalize">{{i.status}}</span></td><td>{{new Date(i.updated_at).toLocaleDateString()}}</td><td class="space-x-3 text-right"><Link :href="`/admin/content/${i.id}/edit`" class="font-bold text-brand-600">Edit</Link><button @click="remove(i.id)" class="font-bold text-red-600">Delete</button></td></tr></tbody></table><p v-if="!items.data.length" class="py-12 text-center text-slate-500">No content found.</p></div></AdminLayout></template>
